["2","France","PAR","2026-05-17","李四","中介B","NUIT","22:00","06:00","60","SIGNATURE","Observations","正常;夜班",false]
["3","Netherlands","AMS","2026-05-17","王五","中介C","MATIN","08:30","17:30","60","","","手写",false]
